#include <iostream>

int gcd(int a, int b) {
    if (a > b) {
        std::swap(a, b);
    }

    if (a == 0 || b == 0) {
        return a + b;
    }

    int result = 1;

    while (true) {
        int remain = b % a;

        if (remain == 0) {
            result *= a;
            break;
        } else {
            b = a;
            a = remain;
        }
    }
    return result;
}

int main() {
    int simon, antisimon, stones;
    std::cin >> simon >> antisimon >> stones;

    while (true) {
        int simonQuota = gcd(simon, stones);

        if (simonQuota <= stones) {
            stones -= simonQuota;
        } else {
            std::cout << 1 << std::endl;
            return 0;
        }

        int antiQuota = gcd(antisimon, stones);

        if (antiQuota <= stones) {
            stones -= antiQuota;
        } else {
            std::cout << 0 << std::endl;
            return 0;
        }
    }
}

